    if key == "alpha" and class_name == "BestSubsetRegressor":
        return {"summary": "Цена одного выбранного признака в точном L0-поиске BestSubsetRegressor.", "details": "К средней квадратичной ошибке добавляется alpha, умноженная на число используемых коэффициентов. Штраф зависит от размера набора, не от величины ненулевого coefficient.", "example": "alpha=0.1 добавляет штраф 0.3 поднабору из трех признаков.", "cautions": ["Перебор ограничен числом выходных признаков; max_features ограничивает размер поднабора."]}
    if key == "n_components" and class_name == "PCA":
        return {"summary": "Размер или правило выбора пространства главных компонент PCA.", "details": "Int задает число координат. Float между 0 и 1 при подходящем solver задает требуемую долю объясненной дисперсии; 'mle' использует поддержанную оценку размерности.", "example": "2 дает две координаты; 0.95 выбирает достаточно компонент для 95% train-дисперсии при соответствующем solver.", "cautions": ["Доля дисперсии не является долей объясненного target; ограничения зависят от solver и формы X."]}
    if key == "subsample" and class_name == "QuantileTransformer":
        return {"summary": "Максимальное число train-строк для оценки квантилей QuantileTransformer.", "details": "Целое число ограничивает случайную обучающую подвыборку; None отключает такой subsampling. Это число строк, не доля 0..1.", "example": "subsample=10000 оценивает quantile map по максимум десяти тысячам train-строк.", "cautions": ["Малая подвыборка может хуже описать хвост; validation не участвует в обучении quantile map."]}
    if key == "categories" and class_name == "OneHotEncoder":
        return {"summary": "Список категорий каждого входа и порядок их выходных one-hot индикаторов.", "details": "auto учит словарь на train. Явный список фиксирует допустимые категории и порядок выходных столбцов.", "example": "['low','medium','high'] задает три отдельных индикатора в указанном порядке, а не числовые коды 0,1,2.", "cautions": ["Drop и rare-category grouping могут изменить выход; это не ordinal rank категории."]}
    if key == "categories" and class_name == "TargetEncoder":
        return {"summary": "Допустимые категории каждого входного столбца TargetEncoder.", "details": "auto учит словарь на train; каждой категории затем соответствует сглаженная статистика y, а не ее порядковый номер.", "example": "Список городов фиксирует словарь, но encoded value города определяется train-ответами и cross-fitting.", "cautions": ["Порядок списка не делает категорию величиной; y validation не используется для ее статистики."]}
