    if key == "algorithm" and class_name in {"KMeans", "BisectingKMeans"}:
        return {"summary": "Вычислительный вариант обновления центров KMeans.", "details": "lloyd выполняет обычное назначение и обновление, elkan использует неравенства расстояний для сокращения сравнений.", "example": "Elkan может быстрее работать для хорошо разделенных групп, но хранит дополнительные bounds.", "cautions": ["Потребление памяти и доступность зависят от класса и входа."]}
    if key == "algorithm" and class_name == "TruncatedSVD":
        return {"summary": "Численный способ приближенного SVD без центрирования матрицы.", "details": "randomized использует случайное подпространство; arpack — итеративный eigen solver.", "example": "При нескольких сотнях нужных компонент randomized может работать иначе по времени, чем arpack.", "cautions": ["Точные ограничения n_components различаются; n_iter относится к randomized refinement."]}
