    if key == "max_features" and class_name in {"BestSubsetRegressor", "BestSubsetRegression"}:
        return {"summary": "Максимальное число признаков в рассматриваемой регрессии выбора поднабора.", "details": "Ограничивает размер combinatorial subset, а не число кандидатов split дерева.", "example": "При max_features=3 ищутся допустимые комбинации не больше трех признаков.", "cautions": ["Число комбинаций быстро растет с числом входов; контроль бюджета обязателен."]}
