    if key == "degree" and class_name in {"PolynomialFeatures", "SplineTransformer"}:
        return {"summary": "Степень создаваемых полиномиальных признаков или локальных spline частей.", "details": "PolynomialFeatures со степенью 2 добавляет квадраты и произведения; SplineTransformer создает локальный basis соответствующей степени.", "example": "Для x=3 degree=2 PolynomialFeatures может дать 1,3,9; у spline число выходов зависит также от n_knots.", "cautions": ["Это не degree SVM poly kernel; расширение X может резко увеличить память."]}
